#define SYS_GETDENTS64 217
#define BUF_SIZE 4096

struct linux_dirent64 {
    uint64_t d_ino;        // Inode number
    int64_t d_off;         // Offset to next entry
    unsigned short d_reclen; // Length of this record
    unsigned char d_type;  // File type (DT_REG, DT_DIR, etc.)
    char d_name[];         // Filename (NUL-terminated)
};

char buffer[BUF_SIZE];
int dir_fd = 3;  // Assumed open directory FD
long bytes_read;

// Standard syscall invocation
bytes_read = syscall(SYS_GETDENTS64, dir_fd, buffer, BUF_SIZE);

if (bytes_read > 0) {
    // Process buffer entries
}
